import type { Account, Gemini, Lang, News, Turn } from '../types'

// Pure helpers shared by the hooks module and the panel's drawing module.
export const LABEL = 15
export const BRAND = '#01b7af'
export const GEMINI_COLOR = '#af87ff' // bravesline's 256-colour 141

export const LABELS = {
  es: {
    session: 'SESIÓN', time: 'Tiempo', branch: 'Rama', noGit: 'Sin Git',
    tokens: 'TOKENS', lastPrompt: 'Último pedido', prompt: 'Pedido', prompts: 'pedidos',
    waitAnswer: 'esperando la primera respuesta', waitResponse: 'esperando la primera respuesta',
    context: 'CONTEXTO', used: 'Usado', tokensRow: 'Tokens',
    totals: 'TOTALES', sessionRow: 'Sesión', last5h: 'Últimas 5h', last7d: 'Últimos 7d',
    cost: 'COSTO', billing: 'Facturación', subscription: 'Suscripción', detecting: 'detectando…',
    wouldCost: 'Costaría', spent: 'Gastado', atApi: 'a precio de API',
    quiet: 'en silencio', model: 'Modelo', step: 'Paso', doing: 'Haciendo', elapsed: 'Tiempo', contextRow: 'Contexto',
    tools: 'HERRAMIENTAS', calls: 'usos', none: 'ninguna todavía',
    opened: 'Panel de Braves abierto.', closed: 'Panel de Braves cerrado.',
    plan: 'Plan listo para revisar', failed: 'falló', denied: 'denegado', commit: 'Commit', ship: 'Merge / release publicado', sprintDemo: 'Trotando 80 s por los cuatro paisajes.', peek: 'Se asoma por el borde.', sit: 'Se sienta en la orilla.', lift: 'Se asoma a revisar el código.', scratch: 'Se rasca la cabeza.', sleep: 'Se va a una esquina a dormir.', neo: 'Golpe arriba y onda expansiva.',
  },
  en: {
    session: 'SESSION', time: 'Time', branch: 'Branch', noGit: 'No Git',
    tokens: 'TOKENS', lastPrompt: 'Last prompt', prompt: 'Prompt', prompts: 'prompts',
    waitAnswer: 'waiting for the first answer', waitResponse: 'waiting for the first response',
    context: 'CONTEXT', used: 'Used', tokensRow: 'Tokens',
    totals: 'TOTALS', sessionRow: 'Session', last5h: 'Last 5h', last7d: 'Last 7d',
    cost: 'COST', billing: 'Billing', subscription: 'Subscription', detecting: 'detecting…',
    wouldCost: 'Would cost', spent: 'Spent', atApi: 'at API prices',
    quiet: 'quiet', model: 'Model', step: 'Step', doing: 'Doing', elapsed: 'Elapsed', contextRow: 'Context',
    tools: 'TOOLS', calls: 'calls', none: 'none yet',
    opened: 'Braves panel opened.', closed: 'Braves panel closed.',
    plan: 'Plan ready to review', failed: 'failed', denied: 'denied', commit: 'Commit', ship: 'Merge / release shipped', sprintDemo: 'Jogging 80 s through the four backdrops.', peek: 'Peeking past the edge.', sit: 'Sitting at the edge.', lift: 'Peeking into the code.', scratch: 'Scratching its head.', sleep: 'Off to a corner to sleep.', neo: 'A punch up and a shockwave.',
  },
} satisfies Record<Lang, Record<string, string>>

// Same thresholds as bravesline: context warns earlier than the rate windows.
export const colorFor = (pct: number, warn = 50, crit = 80) =>
  pct >= crit ? 'error' : pct >= warn ? 'warning' : 'success'

export const fmtTokens = (n: number) =>
  n >= 1e6 ? `${(n / 1e6).toFixed(1)}M` : n >= 1e3 ? `${(n / 1e3).toFixed(1)}k` : `${n}`

export const fmtDuration = (ms: number) => {
  const min = Math.max(0, Math.floor(ms / 60000))
  return min >= 60 ? `${Math.floor(min / 60)}h ${min % 60}m` : `${min}m`
}

export const bar = (pct: number, cells = 12) => {
  const full = Math.round((Math.min(100, Math.max(0, pct)) / 100) * cells)
  return '▰'.repeat(full) + '▱'.repeat(cells - full)
}

// Rate-limit windows only exist on a subscription; before the first response neither shows.
export const planOf = (rateLimits: readonly unknown[], hasResponse: boolean) =>
  rateLimits.length > 0 ? 'subscription' : hasResponse ? 'api' : 'unknown'

/** Reads `claude auth status`: a claude.ai login bills the subscription, anything else the API. */
export const accountOf = (json: string, home: string): Account | null => {
  try {
    const a = JSON.parse(json) as { authMethod?: string; subscriptionType?: string }
    const isSubscription = a.authMethod === 'claude.ai'
    const tier = a.subscriptionType ? a.subscriptionType[0]!.toUpperCase() + a.subscriptionType.slice(1) : ''
    return { isSubscription, plan: isSubscription ? `Claude ${tier}`.trim() : 'API', home }
  } catch {
    return null
  }
}

export const tildePath = (path: string, home: string) =>
  home && path.startsWith(home) ? '~' + path.slice(home.length) : path

/**
 * Parses `gemini-dispatch.sh --status`: "<state>\t<pct>\t<text>", or nothing when idle.
 * The text reads "model · #step · tool Ns · elapsed · tok:▰▱ used / window".
 */
export const parseGemini = (raw: string): Gemini | null => {
  const line = raw.trim()
  if (!line) return null
  const [state = 'run', pct = '', text = ''] = line.split('\t')
  const parts = text.split(' · ')
  const tok = parts.findIndex(p => p.startsWith('tok:'))
  const tokens = tok >= 0 ? (parts.splice(tok, 1)[0] ?? '').replace(/^tok:\S*\s*/, '') : ''
  const [model = '', step = '', doing = '', elapsed = ''] = parts
  return { isSlow: state === 'slow', pct: pct === '' ? null : Number(pct), model, step, doing, elapsed, tokens }
}

export const untilReset = (iso: string | undefined, at: number) =>
  iso ? ` ↺ ${fmtDuration(Date.parse(iso) - at)}` : ''

// The braves toolbox's own setting: the language the user talks in. Unset means Spanish.
export const langOf = (json: string): Lang => {
  try {
    return String(JSON.parse(json).language ?? 'es').toLowerCase().startsWith('en') ? 'en' : 'es'
  } catch {
    return 'es'
  }
}

/** Everything the panel draws, computed by the hooks module and handed to the Client as plain data. */
export type View = {
  lang: Lang
  still: boolean
  working: boolean
  cue: { name: string; n: number }
  version: string
  model: string
  plan: string | null
  cwd: string
  time: string
  branch: string
  last: Turn | null
  prev: Turn[]
  ctx: { percent: number; tokens: number; window: number } | null
  total: number
  prompts: number
  rates: { label: string; pct: number; reset: string }[]
  billing: 'subscription' | 'api' | 'unknown'
  usd: number | null
  gemini: Gemini | null
  tools: [string, number][]
  room: number
  news: News[]
  sprint: boolean
}

export type Run = { text: string; color?: string }

// A ticker window: the runs as one looping tape, `width` cells from `offset`; still when it fits.
export function marquee(items: Run[], width: number, offset: number): Run[] {
  const cells = items.flatMap(r => [...[...r.text].map(ch => ({ ch, color: r.color })), ...[...'   ◆   '].map(ch => ({ ch, color: undefined as string | undefined }))])
  if (cells.length === 0 || width <= 0) return []
  const fits = cells.length - 7 <= width
  const shown = fits ? cells.slice(0, cells.length - 7) : Array.from({ length: width }, (_, i) => cells[(offset + i) % cells.length]!)
  const runs: Run[] = []
  for (const c of shown) {
    const last = runs.at(-1)
    if (last && last.color === c.color) last.text += c.ch
    else runs.push({ text: c.ch, color: c.color })
  }
  return runs
}

// A headline stays on the ticker this long.
export const NEWS_TTL = 5 * 60000

// The title a `git commit -m` / `-qm` / `-am` carries; empty for a heredoc or an editor.
export function commitTitle(command: string): string {
  const m = /\s-[a-zA-Z]*m\s+(?:"([^"\n]+)|'([^'\n]+))/.exec(command)
  return m?.[1] ?? m?.[2] ?? ''
}

files.hooks/mascot.ts:
// The braves mascot, drawn by Carlos in the Unicode Mascot Animator
// (uma.sujumayas.com) and imported into sprites.ts with tools/import-sprites.py.
// Poses are 9 x 3 cells of quadrant blocks (laptop scenes 13 x 3); some carry a
// fourth row on top for effects: hearts, z's, a question mark.

import { PALETTE, SEQUENCES, SPRITES } from './sprites'

export const STAGE_COLUMNS = 9
export const STAGE_ROWS = 4
// 50 so a 100 ms walk step is exactly two ticks (at 70 they alternated 70/140 and the legs shimmered).
export const TICK_MS = 50

export type NeoPose = 'neo-kneel' | 'neo-kneel-2'
export type Pose = keyof typeof SPRITES | NeoPose

/** A step in a short performance: show `pose` for `ms`. */
export type Beat = readonly [Pose, number]

const { work, 'work-desktop': workDesktop, ...acts } = SEQUENCES
/** The editor's timelines (hello, jump, celebrate, poke, idle, ...); the work routines play apart. */
export const ACTS: Record<keyof typeof acts, readonly Beat[]> = acts

// ── Working ─────────────────────────────────────────────────────────────────
// While Claude works the mascot loops a routine at a laptop or at a desktop
// (one or the other per turn): types, glances at the prompt, winks, scratches its head.
export const SCENES = { laptop: work, desktop: workDesktop }
export type Scene = keyof typeof SCENES

/** Which step of `scene`'s routine plays `ms` into the loop. */
export function workAt(ms: number, scene: Scene = 'laptop'): number {
  const steps = SCENES[scene]
  let t = ms % steps.reduce((sum, [, d]) => sum + d, 0)
  for (let i = 0; i < steps.length; i++) {
    t -= steps[i]![1]
    if (t < 0) return i
  }
  return 0
}

export type Run = { text: string; color?: string; bg?: string }

type Drawn = { rows: readonly string[]; ink: readonly string[]; back?: readonly string[] }

// Neo's three-point landing/launch stance: body low, one fist planted on the floor, one knee flat,
// sunglasses on. Frame 2 lifts the body off the floor by an eighth of a cell, for an energy-building tremble.
export const KNEEL: Record<NeoPose, Drawn> = {
  'neo-kneel': {
    rows: ['         ', '         ', '▬▬██━██▬▬', '▗███████▄'],
    ink: ['         ', '         ', '777777777', '000000000'],
    back: ['         ', '         ', ' 0  0  0 ', '         '],
  },
  'neo-kneel-2': {
    rows: ['         ', '         ', '▬▬██━██▬▬', '▗▇▇▇▇▇▇▇▄'],
    ink: ['         ', '         ', '777777777', '000000000'],
    back: ['         ', '         ', ' 0  0  0 ', '         '],
  },
}

// ponytail: the editor gives each cell one color, but the frame of the sunglasses is black over the
// teal face, so the glasses row is painted here: lenses, a bridge between them and arms that stick
// out past the face, across the middle of the lenses: a heavy line (━, drawn centred in the cell) for
// the bridge and a thicker bar (▬) for the arms, in black over a teal cell background.
const ARMS = new Set<string>(['shades', 'shades-shine'])
function drawn(pose: Pose): Drawn {
  if (pose in KNEEL) return KNEEL[pose as NeoPose]
  const { rows, ink } = SPRITES[pose as keyof typeof SPRITES]
  if (!ARMS.has(pose)) return { rows, ink }
  return {
    rows: rows.map((r, i) => (i === 1 ? '▬▬██━██▬▬' : r)),
    ink: ink.map((r, i) => (i === 1 ? '777777777' : r)),
    back: rows.map((r, i) => (i === 1 ? ' 0  0  0 ' : ' '.repeat([...r].length))),
  }
}

// Each quadrant block and its mirror image, so a sprite drawn facing right can face left.
const MIRROR: Record<string, string> = { '▐': '▌', '▌': '▐', '▛': '▜', '▜': '▛', '▙': '▟', '▟': '▙', '▘': '▝', '▝': '▘', '▖': '▗', '▗': '▖', '▞': '▚', '▚': '▞' }

/** A sprite flipped left to right: each row reversed, each block swapped for its mirror. */
export function mirror({ rows, ink, back }: Drawn) {
  const flip = (line: string) => [...line].reverse().join('')
  return { rows: rows.map(r => [...r].reverse().map(ch => MIRROR[ch] ?? ch).join('')), ink: ink.map(flip), ...(back && { back: back.map(flip) }) }
}

/** The sprite for `pose`, or with `work` set, that step of `scene`'s routine; `flip` faces it left. */
export function toRuns(pose: Pose, work?: number, scene: Scene = 'laptop', flip = false): Run[][] {
  const steps = SCENES[scene]
  const art = drawn(work === undefined ? pose : steps[work % steps.length]![0])
  const sprite = flip ? mirror(art) : art
  // Sprites without an effects row sit on the floor: an empty row on top keeps the stage still.
  const pad = STAGE_ROWS - sprite.rows.length
  const rows = [...Array<string>(pad).fill(' '), ...sprite.rows]
  const ink = [...Array<string>(pad).fill(' '), ...sprite.ink]
  const back = [...Array<string>(pad).fill(' '), ...(sprite.back ?? [])]
  return rows.map((line, r) => {
    const runs: Run[] = []
    ;[...line].forEach((text, c) => {
      const i = ink[r]![c]
      const color = i === undefined || i === ' ' ? undefined : PALETTE[Number(i)]
      const b = back[r]?.[c]
      const bg = b === undefined || b === ' ' ? undefined : PALETTE[Number(b)]
      const prev = runs.at(-1)
      if (prev && prev.color === color && prev.bg === bg) prev.text += text
      else runs.push(bg ? { text, color, bg } : { text, color })
    })
    return runs
  })
}

// ── Camera ──────────────────────────────────────────────────────────────────
// Each quadrant block as its four pixels (top-left, top-right, bottom-left, bottom-right);
// legs and other partial blocks count as their nearest quadrants, effects glyphs drop out.
const QUADS = ' ▘▝▀▖▌▞▛▗▚▐▜▄▙▟█'
// Half the thickness of the centred bars, as a fraction of the cell's height.
const BANDS: Record<string, number> = { '━': 0.15, '▬': 0.25 }
const BITS: Record<string, number> = { ...Object.fromEntries([...QUADS].map((ch, i) => [ch, i])), '▆': 12, '▅': 12, '▂': 12, '▁': 12, '▃': 12, '▇': 15 }

// The eyes on the 18 x 8 pixel grid of a padded sprite: between the two notches of the face row.
const EYES = { x: 9, y: 3.5 }

/**
 * The stage `across` cells wide with the camera zoomed `scale` times on the mascot's eyes.
 * At scale 1 it matches the sprite drawn at column `x`; as the scale grows the eyes slide to the
 * middle of the stage. Nearest-pixel sampling: the quadrant blocks are the pixels.
 */
export function zoomed(pose: Pose, across: number, x: number, scale: number, top: number, lens?: number): Run[][] {
  // Landed (lens 0) is simply the shades pose; in flight, the lenses ride over the bare face.
  const base = drawn(lens === undefined ? pose : lens > 0 ? 'default' : 'shades')
  const shades = lens ? drawn('shades') : undefined
  type Hit = { color: string; back: boolean } | undefined
  const sample = ({ rows, ink, back }: Drawn, sx: number, sy: number): Hit => {
    const px = Math.floor(sx)
    const py = Math.floor(sy)
    const pad = STAGE_ROWS - rows.length
    const r = Math.floor(py / 2) - pad
    const c = Math.floor(px / 2)
    const ch = [...(rows[r] ?? '')][c]
    if (ch === undefined) return undefined
    // The frame of the glasses sits across the middle of its cell, at any zoom: ━ thin, ▬ thicker.
    const band = BANDS[ch]
    const on = band ? Math.abs(sy / 2 - Math.floor(sy / 2) - 0.5) < band : (BITS[ch] ?? 0) >> ((py & 1) * 2 + (px & 1)) & 1
    if (!on) {
      const b = back?.[r]?.[c]
      return b === undefined || b === ' ' ? undefined : { color: PALETTE[Number(b)]!, back: true }
    }
    const i = [...ink[r]!][c]
    return i === undefined || i === ' ' ? undefined : { color: PALETTE[Number(i)]!, back: false }
  }
  // Where the eyes land on screen: from where it stands toward the middle as the camera closes in.
  const k = (scale - 1) / Math.max(1, top - 1)
  const ax = (2 * x + EYES.x) * (1 - k) + across * k
  const ay = EYES.y * (1 - k) + STAGE_ROWS * k
  return Array.from({ length: STAGE_ROWS }, (_, r) => {
    const runs: Run[] = []
    for (let c = 0; c < across; c++) {
      const hits = [0, 1, 2, 3].map((q): Hit => {
        const sx = EYES.x + (2 * c + (q & 1) + 0.5 - ax) / scale
        const sy = EYES.y + (2 * r + (q >> 1) + 0.5 - ay) / scale
        const lensHit = shades && sample(shades, sx, sy + lens!)
        return lensHit?.color === PALETTE[7] && !lensHit.back ? lensHit : sample(base, sx, sy)
      })
      // Two colors in a cell (the frame of the glasses): the glyph takes the drawn color, the
      // background the cell-background color, as in the sprite itself.
      const color = (hits.find(h => h && !h.back) ?? hits.find(h => h))?.color
      let bits = 0
      let bg: string | undefined
      hits.forEach((h, q) => {
        if (h && h.color === color) bits |= 1 << q
        else if (h) bg ??= h.color
      })
      const text = QUADS[bits]!
      const prev = runs.at(-1)
      if (prev && prev.color === color && prev.bg === bg) prev.text += text
      else runs.push(bg ? { text, color, bg } : { text, color })
    }
    return runs
  })
}

